const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
// The Calendar of 4.3, 4.4.4 and 5.1.1 uses AOSP's datetimepicker (dtp.js, generated by docs/datetimepicker.py).
class MO{observe(){}}
for(const v of ['4.3','4.4.4','5.1.1']){
  const ctx={window:{},document:{addEventListener(){},documentElement:{}},MutationObserver:MO,Intl,Date,Math};vm.runInNewContext(fs.readFileSync(`versions/${v}/dtp.js`,'utf8'),ctx);
  const D=ctx.window.DateTimePicker;
  // Date: the day-of-week header, month / day / year, the month grid with the selected day, Done.
  const s=D.fromValue('date','2013-07-24',{setAction:'dtp-set'});
  let html=D.render(s,'en-US',new Date(2013,6,1));
  assert.match(html,/dtp-header">WEDNESDAY</,v);assert.match(html,/<span>JUL<\/span><b>24<\/b>/,v);assert.match(html,/dtp-year" data-action="dtp-view" data-id="year">2013/,v);
  assert.match(html,/class="sel" data-action="dtp-day" data-id="2013-07-24"/,v);assert.match(html,/class=" today" data-action="dtp-day" data-id="2013-07-01"/,v);assert.match(html,/>Done</,v);
  assert.match(D.render(s,'hu-HU'),/>Kész</,v);
  D.handle('dtp-month','1',s);assert.match(D.render(s,'en-US'),/August 2013/,v);assert.equal(D.iso(s),'2013-07-24',v);
  D.handle('dtp-day','2013-08-02',s);assert.equal(D.iso(s),'2013-08-02',v);
  D.handle('dtp-view','year',s);assert.match(D.render(s,'en-US'),/class="sel" data-action="dtp-year" data-id="2013"/,v);D.handle('dtp-year','2012',s);assert.equal(D.iso(s),'2012-08-02',v);assert.equal(s.view,'day',v);
  const feb=D.fromValue('date','2012-02-29');D.handle('dtp-view','year',feb);D.handle('dtp-year','2013',feb);assert.equal(D.iso(feb),'2013-02-28',v);
  // Time: hours first, then minutes; AM / PM circles on a 12-hour clock, the inner 13-00 ring on a 24-hour clock.
  const t=D.fromValue('time','09:05',{hour24:false});html=D.render(t,'en-US');
  assert.match(html,/class="on" data-action="dtp-mode" data-id="hour">9</,v);assert.match(html,/dtp-ampm-label" data-action="dtp-ampm">AM</,v);assert.equal((html.match(/<circle class="dtp-ampm/g)||[]).length,2,v);
  D.handle('dtp-radial','hour:15',t);assert.equal(t.mode,'minute',v);D.handle('dtp-radial','min:42',t);assert.equal(D.hhmm(t),'15:42',v);D.handle('dtp-radial','ampm:0',t);assert.equal(D.hhmm(t),'03:42',v);
  html=D.render(D.fromValue('time','21:00',{hour24:true}),'de-DE');assert.match(html,/>21</,v);assert.match(html,/>13</,v);assert.doesNotMatch(html,/dtp-ampm/,v);
  // The Calendar editor has no browser date / time fields, no bar of its own and no glyphs; dtp.js is loaded.
  const cal=fs.readFileSync(`versions/${v}/calendar.js`,'utf8');
  assert.doesNotMatch(cal,/'date','Start date','date'/,v);assert.doesNotMatch(cal,/cal-nav/,v);assert.doesNotMatch(cal,/[‹›▾]/,v);assert.match(cal,/data-action="calpick"/,v);
  assert.match(fs.readFileSync(`versions/${v}/index.html`,'utf8'),/dtp\.js\?v=/,v);
}
console.log('datetimepicker ok');
